  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'SIP 编号',
  `item_id` bigint NOT NULL COMMENT '物料产品 ID',
  `sort` int DEFAULT NULL COMMENT '排列顺序',
  `process_id` bigint DEFAULT NULL COMMENT '工序 ID',
