  `specification` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '型号规格',
  `tool_type_id` bigint NOT NULL COMMENT '工具类型编号',
  `quantity` int NOT NULL DEFAULT '1' COMMENT '数量',
